  3	import javax.sql.DataSource;
  4	
  5	public final class Main {
  6	    public static void main(String[] args) {
  7	        String url = require("DB_URL");
  8	        DataSource ds = Db.connect(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
  9	        String port = System.getenv("PORT");
 10	        Api.create(new ReservationService(new Store(ds))).start(port == null || port.isBlank() ? 7070 : Integer.parseInt(port.trim()));
 11	    }
 12	
 13	    private static String require(String name) {
 14	        String v = System.getenv(name);
 15	        if (v == null || v.isBlank()) throw new IllegalStateException("Variável de ambiente " + name + " é obrigatória");
 16	        return v;
 17	    }
 18	}
 19	package br.com.marealta;
 20	
 21	import br.com.marealta.Model.*;
 22	import com.fasterxml.jackson.core.JsonProcessingException;
 23	import com.fasterxml.jackson.databind.JsonNode;
 24	import com.fasterxml.jackson.databind.ObjectMapper;
 25	import com.fasterxml.jackson.databind.SerializationFeature;
 26	import io.javalin.Javalin;
 27	import io.javalin.http.Context;
 28	import java.time.LocalDate;
 29	import java.time.YearMonth;
 30	import java.time.format.DateTimeParseException;
 31	import java.util.LinkedHashMap;
 32	import java.util.List;
 33	import java.util.Map;
 34	
 35	public final class Api {
 36	    private static final ObjectMapper JSON = new ObjectMapper().enable(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN);
 37	
 38	    private final ReservationService service;
 39	
 40	    private Api(ReservationService service) {
 41	        this.service = service;
 42	    }
 43	
 44	    public static Javalin create(ReservationService service) {
 45	        Api api = new Api(service);
 46	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
 47	        app.get("/rooms", api::rooms);
 48	        app.post("/reservations", api::create);
 49	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservation(service.get(id(ctx)))));
 50	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, reservation(service.confirm(id(ctx)))));
 51	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, reservation(service.cancel(id(ctx)))));
 52	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, reservation(service.checkIn(id(ctx)))));
 53	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, document(service.checkOut(id(ctx)))));
 54	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, document(service.document(id(ctx)))));
 55	        app.get("/messages", api::messages);
 56	        app.get("/reports/occupancy", ctx -> csv(ctx, service.occupancyCsv(date(ctx.queryParam("date"), "date"))));
 57	        app.get("/reports/revenue", ctx -> csv(ctx, service.revenueCsv(month(ctx.queryParam("month")))));
 58	
 59	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status, e.code, e.getMessage()));
 60	        app.exception(Exception.class, (e, ctx) -> {
 61	            e.printStackTrace();
 62	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
 63	        });
 64	        return app;
 65	    }
 66	
 67	    // ---- handlers
 68	
 69	    private void rooms(Context ctx) {
 70	        List<Map<String, Object>> out = service.rooms().stream().map(r -> obj(
 71	                "number", r.number(), "type", r.type(), "capacity", r.capacity(), "nightlyRate", r.nightlyRate())).toList();
 72	        json(ctx, 200, out);
 73	    }
 74	
 75	    private void messages(Context ctx) {
 76	        List<Map<String, Object>> out = service.messages().stream().map(m -> obj(
 77	                "id", m.id(), "channel", m.channel(), "to", m.to(), "subject", m.subject(), "body", m.body())).toList();
 78	        json(ctx, 200, out);
 79	    }
 80	
 81	    private void create(Context ctx) {
 82	        json(ctx, 201, reservation(service.create(parse(ctx.body()))));
 83	    }
 84	
 85	    // ---- entrada
 86	
 87	    static ReservationService.NewReservation parse(String body) {
 88	        JsonNode n;
 89	        try {
 90	            n = JSON.readTree(body);
 91	        } catch (JsonProcessingException e) {
 92	            throw ApiException.invalid("O corpo não é um JSON válido");
 93	        }
 94	        if (n == null || !n.isObject()) throw ApiException.invalid("O corpo deve ser um objeto JSON");
 95	
 96	        String name = text(n, "guestName");
 97	        String email = text(n, "guestEmail");
 98	        if (name == null) throw ApiException.invalid("guestName é obrigatório");
 99	        if (email == null) throw ApiException.invalid("guestEmail é obrigatório");
100	        Identification ident = identification(n);
101	        LocalDate checkIn = date(text(n, "checkIn"), "checkIn");
102	        LocalDate checkOut = date(text(n, "checkOut"), "checkOut");
103	        if (!checkOut.isAfter(checkIn)) throw ApiException.invalid("A saída deve ser depois da entrada");
104	
105	        JsonNode g = n.get("guests");
106	        if (g == null || !g.isIntegralNumber() || !g.canConvertToInt()) {
107	            throw ApiException.invalid("guests deve ser um número inteiro");
108	        }
109	        if (g.intValue() < 1) throw ApiException.invalid("É preciso ao menos um hóspede");
110	
111	        JsonNode rn = n.get("roomNumber");
112	        if (rn == null || !rn.isIntegralNumber() || !rn.canConvertToInt()) {
113	            throw ApiException.invalid("roomNumber deve ser um número inteiro");
114	        }
115	        String plan = text(n, "ratePlan");
116	        if (plan == null) throw ApiException.invalid("ratePlan é obrigatório");
117	        RatePlan ratePlan;
118	        try {
119	            ratePlan = RatePlan.valueOf(plan);
120	        } catch (IllegalArgumentException e) {
121	            throw ApiException.invalid("ratePlan deve ser STANDARD ou NON_REFUNDABLE");
122	        }
123	        return new ReservationService.NewReservation(rn.intValue(), name, email, ident, checkIn, checkOut,
124	                g.intValue(), ratePlan);
125	    }
126	
127	    /** Exatamente um dos três jeitos: CPF, CNPJ + razão social, ou passaporte + país. */
128	    private static Identification identification(JsonNode n) {
129	        for (String f : List.of("guestCpf", "companyCnpj", "companyName", "guestPassport", "guestCountry")) {
130	            JsonNode v = n.get(f);
131	            if (v != null && !v.isNull() && !v.isTextual()) throw ApiException.invalid(f + " deve ser texto");
132	        }
133	        String cpf = text(n, "guestCpf");
134	        String cnpj = text(n, "companyCnpj");
135	        String company = text(n, "companyName");
136	        String passport = text(n, "guestPassport");
137	        String country = text(n, "guestCountry");
138	        boolean isCpf = cpf != null;
139	        boolean isCompany = cnpj != null || company != null;
140	        boolean isPassport = passport != null || country != null;
141	        if (java.util.stream.Stream.of(isCpf, isCompany, isPassport).filter(b -> b).count() != 1) {
142	            throw ApiException.invalid("Informe guestCpf, ou companyCnpj com companyName, ou guestPassport com guestCountry");
143	        }
144	        if (isCpf) return new Identification.Cpf(cpf);
145	        if (isCompany) {
146	            if (cnpj == null || company == null) throw ApiException.invalid("companyCnpj e companyName vão juntos");
147	            return new Identification.Company(cnpj, company);
148	        }
149	        if (passport == null || country == null) throw ApiException.invalid("guestPassport e guestCountry vão juntos");
150	        return new Identification.Passport(passport, country);
151	    }
152	
153	    /** Texto não vazio, ou null se ausente/nulo/vazio. */
154	    private static String text(JsonNode n, String field) {
155	        JsonNode v = n.get(field);
156	        if (v == null || v.isNull()) return null;
157	        if (!v.isTextual()) throw ApiException.invalid(field + " deve ser texto");
158	        String s = v.asText().trim();
159	        return s.isEmpty() ? null : s;
160	    }
161	
162	    private static LocalDate date(String v, String field) {
163	        if (v == null) throw ApiException.invalid(field + " é obrigatório (formato AAAA-MM-DD)");
164	        try {
165	            return LocalDate.parse(v);
166	        } catch (DateTimeParseException e) {
167	            throw ApiException.invalid(field + " deve estar no formato AAAA-MM-DD");
168	        }
169	    }
170	
171	    private static YearMonth month(String v) {
172	        if (v == null) throw ApiException.invalid("month é obrigatório (formato AAAA-MM)");
173	        try {
174	            return YearMonth.parse(v);
175	        } catch (DateTimeParseException e) {
176	            throw ApiException.invalid("month deve estar no formato AAAA-MM");
177	        }
178	    }
179	
180	    private static long id(Context ctx) {
181	        try {
182	            return Long.parseLong(ctx.pathParam("id"));
183	        } catch (NumberFormatException e) {
184	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não encontrada");
185	        }
186	    }
187	
188	    // ---- saída
189	
190	    private static Map<String, Object> obj(Object... kv) {
191	        Map<String, Object> m = new LinkedHashMap<>();
192	        for (int i = 0; i < kv.length; i += 2) m.put((String) kv[i], kv[i + 1]);
193	        return m;
194	    }
195	
196	    /** Os cinco campos de identificação; os que não se aplicam vão null. */
197	    private static void putIdentification(Map<String, Object> m, Identification id) {
198	        m.put("guestCpf", id instanceof Identification.Cpf c ? c.cpf() : null);
199	        m.put("companyCnpj", id instanceof Identification.Company c ? c.cnpj() : null);
200	        m.put("companyName", id instanceof Identification.Company c ? c.name() : null);
201	        m.put("guestPassport", id instanceof Identification.Passport p ? p.number() : null);
202	        m.put("guestCountry", id instanceof Identification.Passport p ? p.country() : null);
203	    }
204	
205	    static Map<String, Object> reservation(Reservation r) {
206	        Map<String, Object> m = obj("id", r.id(), "roomNumber", r.roomNumber(), "guestName", r.guestName(),
207	                "guestEmail", r.guestEmail());
208	        putIdentification(m, r.identification());
209	        m.put("checkIn", r.checkIn().toString());
210	        m.put("checkOut", r.checkOut().toString());
211	        m.put("guests", r.guests());
212	        m.put("ratePlan", r.ratePlan());
213	        m.put("nights", r.nights());
214	        m.put("subtotal", r.subtotal());
215	        m.put("discount", r.discount());
216	        m.put("total", r.total());
217	        m.put("status", r.status());
218	        m.put("amountPaid", r.amountPaid());
219	        m.put("refund", r.refund());
220	        return m;
221	    }
222	
223	    static Map<String, Object> document(ReservationService.Issued i) {
224	        Reservation r = i.reservation();
225	        Map<String, Object> m = obj("title", i.document().title(), "reservationId", r.id(), "guestName", r.guestName());
226	        putIdentification(m, r.identification());
227	        m.put("roomNumber", r.roomNumber());
228	        m.put("roomType", i.room().type());
229	        m.put("checkIn", r.checkIn().toString());
230	        m.put("checkOut", r.checkOut().toString());
231	        m.put("nights", r.nights());
232	        m.put("subtotal", r.subtotal());
233	        m.put("discount", r.discount());
234	        m.put("total", r.total());
235	        m.put("text", i.document().text());
236	        return m;
237	    }
238	
239	    private static void json(Context ctx, int status, Object body) {
240	        try {
241	            ctx.status(status).contentType("application/json").result(JSON.writeValueAsString(body));
242	        } catch (JsonProcessingException e) {
243	            throw new IllegalStateException(e);
244	        }
245	    }
246	
247	    private static void csv(Context ctx, String body) {
248	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));
249	    }
250	
251	    private static void error(Context ctx, int status, String code, String message) {
252	        json(ctx, status, obj("error", code, "message", message));
253	    }
254	}
255	package br.com.marealta;
256	
257	public class ApiException extends RuntimeException {
258	    public final int status;
259	    public final String code;
260	
261	    public ApiException(int status, String code, String message) {
262	        super(message);
263	        this.status = status;
264	        this.code = code;
265	    }
266	
267	    public static ApiException invalid(String message) {
268	        return new ApiException(400, "INVALID_REQUEST", message);
269	    }
270	
271	    public static ApiException notAllowed(String message) {
272	        return new ApiException(409, "OPERATION_NOT_ALLOWED", message);
273	    }
274	}

