630	    16	    /** Alta temporada: 15/12 até o fim de fevereiro, e julho inteiro. */
631	    17	    public static boolean isHighSeason(LocalDate night) {
632	    18	        int m = night.getMonthValue();
633	    19	        return m == 7 || m == 1 || m == 2 || (m == 12 && night.getDayOfMonth() >= 15);
634	    20	    }
