636	    22	    public static Quote quote(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
637	    23	        BigDecimal subtotal = Money.ZERO;
638	    24	        int nights = 0;
639	    25	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
640	    26	            BigDecimal price = isHighSeason(d) ? Money.round(nightlyRate.multiply(HIGH_SEASON)) : Money.round(nightlyRate);
641	    27	            subtotal = subtotal.add(price);
642	    28	            nights++;
643	    29	        }
644	    30	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
645	    31	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT)) : Money.ZERO;
646	    32	        return new Quote(nights, subtotal, discount, subtotal.subtract(discount));
