    63	    public static DataSource connect(String url, String user, String password) {
    64	        HikariConfig cfg = new HikariConfig();
    65	        cfg.setJdbcUrl(url);
    66	        cfg.setUsername(user);
    67	        cfg.setPassword(password);
    68	        cfg.setMaximumPoolSize(10);
    69	        cfg.setInitializationFailTimeout(-1); // não falha na criação do pool; tentamos abaixo
    70	        HikariDataSource ds = new HikariDataSource(cfg);
    71	        long deadline = System.currentTimeMillis() + 60_000;
    72	        while (true) {
    73	            try {
    74	                init(ds);
    75	                return ds;
    76	            } catch (SQLException e) {
    77	                if (System.currentTimeMillis() > deadline) throw new IllegalStateException("Banco indisponível", e);
    78	                System.err.println("Aguardando o banco: " + e.getMessage());
    79	                try {
    80	                    Thread.sleep(2000);
    81	                } catch (InterruptedException ie) {
    82	                    Thread.currentThread().interrupt();
    83	                    throw new IllegalStateException(ie);
    84	                }
    85	            }
    86	        }
    87	    }
    88	
    89	    static void init(DataSource ds) throws SQLException {
    90	        try (Connection c = ds.getConnection()) {
    91	            c.setAutoCommit(false);
    92	            try (Statement st = c.createStatement()) {
    93	                // Serializa a criação do esquema caso várias instâncias subam juntas.
    94	                st.execute("SELECT pg_advisory_xact_lock(727401)");
    95	                for (String sql : SCHEMA) st.execute(sql);
    96	            }
    97	            c.commit();
    98	        }
    99	    }
