     9	/** Valores em reais, sempre com 2 casas e arredondamento "meio para o par". */
    10	public final class Money {
    11	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
    12	
    13	    private Money() {}
    14	
    15	    public static BigDecimal round(BigDecimal v) {
    16	        return v.setScale(2, RoundingMode.HALF_EVEN);
    17	    }
    18	
    19	    public static BigDecimal of(String v) {
    20	        return round(new BigDecimal(v));
    21	    }
    22	
    23	    /** R$ 1.234,56 (sem o prefixo). */
    24	    public static String pt(BigDecimal v) {
    25	        return format(v, ',', '.');
    26	    }
    27	
    28	    /** 1,234.56 (sem o prefixo). */
    29	    public static String en(BigDecimal v) {
    30	        return format(v, '.', ',');
    31	    }
    32	
    33	    private static String format(BigDecimal v, char decimal, char grouping) {
    34	        DecimalFormatSymbols s = new DecimalFormatSymbols(Locale.ROOT);
    35	        s.setDecimalSeparator(decimal);
    36	        s.setGroupingSeparator(grouping);
    37	        DecimalFormat f = new DecimalFormat("#,##0.00", s);
    38	        f.setRoundingMode(RoundingMode.HALF_EVEN);
    39	        return f.format(round(v));
    40	    }
