     1	package br.com.marealta;
     2	
     3	import br.com.marealta.Model.RatePlan;
     4	import java.math.BigDecimal;
     5	import java.time.LocalDate;
     6	
     7	public final class Pricing {
     8	    private static final BigDecimal HIGH_SEASON = new BigDecimal("1.20");
     9	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    10	    private static final BigDecimal ISS = new BigDecimal("0.05");
    11	
    12	    private Pricing() {}
    13	
    14	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    15	
    16	    /** Alta temporada: 15/12 até o fim de fevereiro, e julho inteiro. */
    17	    public static boolean isHighSeason(LocalDate night) {
    18	        int m = night.getMonthValue();
    19	        return m == 7 || m == 1 || m == 2 || (m == 12 && night.getDayOfMonth() >= 15);
    20	    }
    21	
    22	    public static Quote quote(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    23	        BigDecimal subtotal = Money.ZERO;
    24	        int nights = 0;
    25	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    26	            BigDecimal price = isHighSeason(d) ? Money.round(nightlyRate.multiply(HIGH_SEASON)) : Money.round(nightlyRate);
    27	            subtotal = subtotal.add(price);
    28	            nights++;
    29	        }
    30	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    31	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT)) : Money.ZERO;
    32	        return new Quote(nights, subtotal, discount, subtotal.subtract(discount));
    33	    }
    34	
    35	    public static BigDecimal withheldIss(BigDecimal total) {
    36	        return Money.round(total.multiply(ISS));
    37	    }
    38	}
